			/**
			 * 상세 페이지 CRUD 권한 처리 
			 * @param {"CREATE" | "READ" | "UPDATE"} psType CRUD Type
			 */
			function setDtlCrud(psType) {

			    try {
			        if (psType == "READ") {
			            util.Control.setVisible( app, false, ["btnSave", "btnRestore"] );
			            util.Control.setVisible( app, true,  ["btnUpdate"] );
			            util.Control.setReadOnly(app, true, ["grpData"]);            
			        } else {
			            util.Control.setVisible( app, true,  ["btnSave", "btnRestore"] );
			            util.Control.setVisible( app, false, ["btnUpdate"] );
			            util.Control.setReadOnly(app, false, ["grpData"]);
			        }

			        util.Control.redraw(app, "grpData");

			    } catch(e) {
			        console.log(e);
			    }
			}

			/**
			 * 목록 데이터 조회 서브미션 호출
			 * @param psStatus - 조회 상태(저장 후 조회인 경우에는 'save' 구분값 넘김)
			 */
			function doList(psStatus){

			    util.DataSet.clear(app, "dsOutcomeList");
			    util.DataMap.clear(app, "dmOutcomeDetail");

			    //조회 서브미션 호출
			    util.Submit.send(app, 'subOnload', function(pbSuccess) {
			        if(pbSuccess) {
			            app.lookup("cmnMultifileupload").getFiles(); //파일 목록 가져오기
			            
			            if(psStatus == "save") {
			                //갱신된 데이터가 조회되었습니다.
			                util.Msg.notify(app, "INF-M005");
			            } else {
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			            }
			            setDtlCrud("READ");
			            resetGrp();

			            util.Control.redraw(app, 'grpData');
			        }
			    });
			}

			/**
			 * 데이터 저장 서브미션 호출
			 */
			function doSave(){
			    /*
			    if(ValueUtil.isNull(app.lookup("dmOutcomeDetail").getValue("OUTC_YMD"))) {
			        util.Msg.alert(app, "성과일자를 입력해주세요.");
			        return false;
			    }
			    */
			    var dsSEC330 = app.lookup("dsSEC330");
			    var ddlnAplcnYmd = "10000000"; // 마감일자
			    var ddlnYm = "";               // 마감년월
			    for(var i = 0; i < dsSEC330.getRowCount(); i++){
			        if(dsSEC330.getValue(i, "DDLN_APLCN_YMD") > ddlnAplcnYmd){
			            ddlnAplcnYmd = dsSEC330.getValue(i, "DDLN_APLCN_YMD");
			            ddlnYm = dsSEC330.getValue(i, "DDLN_YM");
			        }
			    }
			    
			    var dsOutcomeList = app.lookup("dsOutcomeList");
			    for(var i = 0; i < dsOutcomeList.getRowCount(); i++){
			        if(ValueUtil.isNull(dsOutcomeList.getValue(i, "OUTC_YMD"))){
			            util.Msg.alert(app, "성과일자를 입력해주세요.");
			            return;    
			        }
			        var outcDate = vdTodayDate.substring(0,7).replace("-", ""); //오늘 년월
			        if(ddlnAplcnYmd == "10000000"){ // 성과 마감일자가 없음
			            
			        } else {
			            var outcYm = dsOutcomeList.getValue(i, "OUTC_YMD").substr(0, 6); // 입력한 성과 년월
			            if(outcYm > ddlnYm){ // 마감 월 이후는 입력 가능
			                
			            } else { // 마감 월 또는 그 이전 월
			                var outcY = ddlnYm.substr(0, 4);
			                var outcM = ddlnYm.substr(4, 6);
			                var outcR = i+1;
			                if(outcYm == ddlnYm){ // 마감 월
			                    if(vsToday > ddlnAplcnYmd){ // 오늘 일자가 성과 마감일 후
			                        var alertMsg = outcY + "년" + outcM + "월의 성과는 마감되었습니다.\n" + outcR + "열의 성과일자를 확인해 주세요."
			                        util.Msg.alert(app, alertMsg);
			                        return;
			                    }
			                } else { // 이전 월 
			                    var alertMsg = outcY + "년" + outcM + "월 이전의 성과는 마감되었습니다.\n" + outcR + "열의 성과일자를 확인해 주세요."
			                    util.Msg.alert(app, alertMsg);
			                    return;
			                }
			            }
			            
			        }
			        
			        if(!ValueUtil.isNull(dsOutcomeList.getValue(i, "PRD_BGNG_YMD"))){
			            if(dsOutcomeList.getValue(i, "PRD_BGNG_YMD") > dsOutcomeList.getValue(i, "PRD_END_YMD")){
			                util.Msg.alert(app, "기간종료일자는 기간 시작일자 이후 여야 합니다.");
			                return;
			            }
			        }
			    }
			    
			    // 그리드 내 컬럼 유효성 체크
			    if (!util.validate(app, "grd5")) return false;

			    var cmnMultifileupload = app.lookup("cmnMultifileupload");//첨부파일
			    cmnMultifileupload.send(function(){

			        // 저장 서브미션 호출
			        util.Submit.send(app, "subSave", function(pbSuccess){
			            if(pbSuccess){
			                var dsSearch = app.lookup("dsSearch");
			                if(dsSearch.getRowCount() > 1){
			                    app.close();
			                } else {
			                    doList("save");
			                }
			            }
			        });
			    });
			}

